"""Shipping against orders, order status, invoices and the report."""
from .parsing import counting_order
from .pricing import money, price_order


def order_note(order):
    return "order %s" % order.id


def shipped_so_far(order, movements):
    """sku -> units already shipped for this order, capped at the quantity ordered."""
    note = order_note(order)
    sent = {sku: 0 for sku, _ in order.lines}
    for move in movements:
        if move.quantity < 0 and move.note == note and move.sku in sent:
            sent[move.sku] -= move.quantity
    return {sku: min(qty, sent[sku]) for sku, qty in order.lines}


def available_on(sku, date, movements):
    """Most that can leave the shelf on `date` without any later movement going below zero."""
    balance = at_date = 0
    later = None
    for move in counting_order(movements):
        if move.sku != sku:
            continue
        balance += move.quantity
        if move.date <= date:
            at_date = balance
        else:
            later = balance if later is None else min(later, balance)
    return max(0, at_date if later is None else min(at_date, later))


def plan_fulfil(order, date, movements):
    """Return [(sku, shipped now, backordered)] for each order line."""
    moves = list(movements)
    sent = shipped_so_far(order, moves)
    plan = []
    for sku, quantity in order.lines:
        owed = quantity - sent[sku]
        ship = min(owed, available_on(sku, date, moves))
        if ship > 0:
            moves.append(_Shipment(date, sku, -ship))
        plan.append((sku, ship, owed - ship))
    return plan


class _Shipment:
    note = ""
    line = 0

    def __init__(self, date, sku, quantity):
        self.date, self.sku, self.quantity = date, sku, quantity


def order_status(order, shipped):
    if all(shipped[sku] >= qty for sku, qty in order.lines):
        return "complete"
    if not any(shipped.values()):
        return "open"
    return "partial"


def invoice_quote(order, catalog, movements):
    """Quote over what has shipped, or None when nothing has."""
    sent = shipped_so_far(order, movements)
    if not any(sent.values()):
        return None
    return price_order(order, catalog, sent)


def report_rows(orders, catalog, movements):
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, int(o.id[3:]), o.id)):
        sent = shipped_so_far(order, movements)
        invoice = invoice_quote(order, catalog, movements)
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": order_status(order, sent),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(sent.values()),
            "quoted": price_order(order, catalog).total,
            "invoiced": invoice.total if invoice else money(0),
        })
    return rows
"""Stock levels, status, what to buy and history."""
from .parsing import counting_order, first_below_zero

__all__ = ["stock_levels", "status", "low_items", "history", "format_delta",
           "counting_order", "first_below_zero"]


def stock_levels(catalog, movements):
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        levels[move.sku] = levels.get(move.sku, 0) + move.quantity
    return levels


def status(onhand, reorder):
    if onhand <= 0:
        return "out"
    return "low" if onhand <= reorder else "ok"


def low_items(catalog, levels):
    """(sku, onhand, reorder, buy) for every low or out product, by SKU."""
    items = []
    for sku in sorted(catalog):
        onhand, reorder = levels.get(sku, 0), catalog[sku].reorder
        if status(onhand, reorder) != "ok":
            items.append((sku, onhand, reorder, max(1, 2 * reorder - onhand)))
    return items


def history(sku, movements):
    """(movement, balance after it) for one SKU, in counting order."""
    balance = 0
    rows = []
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def format_delta(quantity):
    return "%+d" % quantity
