            "quoted": price_order(order, catalog).total,
            "invoiced": invoice.total if invoice else money(0),
        })
    return rows
"""Stock levels, status, what to buy and history."""
from .parsing import counting_order, first_below_zero

__all__ = ["stock_levels", "status", "low_items", "history", "format_delta",
           "counting_order", "first_below_zero"]


def stock_levels(catalog, movements):
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        levels[move.sku] = levels.get(move.sku, 0) + move.quantity
    return levels


def status(onhand, reorder):
    if onhand <= 0:
        return "out"
    return "low" if onhand <= reorder else "ok"


def low_items(catalog, levels):
    """(sku, onhand, reorder, buy) for every low or out product, by SKU."""
    items = []
    for sku in sorted(catalog):
        onhand, reorder = levels.get(sku, 0), catalog[sku].reorder
        if status(onhand, reorder) != "ok":
            items.append((sku, onhand, reorder, max(1, 2 * reorder - onhand)))
    return items


def history(sku, movements):
    """(movement, balance after it) for one SKU, in counting order."""
    balance = 0
    rows = []
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def format_delta(quantity):
    return "%+d" % quantity
